    #[test]
    fn gradient_midpoint_is_between_green_and_yellow() {
        // 25% should be halfway between green and yellow
        let color = gradient_color(0.25, &Theme::gh_dark());
        let expected = interpolate_rgb(GRADIENT_GREEN, GRADIENT_YELLOW, 0.5);
        assert_eq!(color, expected);
    }

